#[test]
fn original_all12_records_refuse_unknown_shapes_fields_addresses_and_source_substitution() {
    for (index, m) in fixtures().into_iter().enumerate() {
        let r = RULES[index];
        assert!(m.validate().is_ok());
        assert!(require_record(r.0, r.1, r.2, &m).is_ok());
        for change in 0..15 {
            let mut bad = m.clone();
            match change {
                0 => bad.entry.push('x'),
                1 => bad.binary_sm = 80,
                2 => bad.grid[0] += 1,
                3 => bad.grid[1] += 1,
                4 => bad.block[0] += 1,
                5 => bad.dynamic_shared_bytes = 4,
                6 => bad.attributes = CubinLaunchAttributes::Unsupported,
                7 => bad.parameters[0].template[0] ^= 1,
                8 => {
                    bad.parameters.last_mut().unwrap().template.pop();
                }
                9 => bad.fixups[0].binding_offset = 1,
                10 => bad.fixups[0].extent -= 1,
                11 => bad.fixups[0].byte_offset += 4,
                12 => bad.bindings[0].io = CubinIo::Read,
                13 => bad.bindings[0].bytes += 1,
                _ => bad.bindings[0].alignment = 8,
            };
            assert!(
                require_record(r.0, r.1, r.2, &bad).is_err(),
                "record{index} field{change}"
            );
        }
        assert!(require_record(r.0, r.1 + 1, r.2, &m).is_err());
        let mut sha = r.0;
        sha[0] ^= 1;
        assert!(require_record(sha, r.1, r.2, &m).is_err());
        assert!(require_record(r.0, r.1, 80, &m).is_err());
    }
}
#[test]
fn arange32_and_full1m_records_cannot_substitute_their_extents_or_grids() {
    let m = fixtures();
    let r = RULES[0];
    assert!(require_record(r.0, r.1, r.2, &m[6]).is_ok());
    let mut bad = m[6].clone();
    bad.grid = m[0].grid;
    assert!(require_record(r.0, r.1, r.2, &bad).is_err());
    let mut bad = m[0].clone();
    bad.bindings[0].bytes = m[6].bindings[0].bytes;
    assert!(require_record(r.0, r.1, r.2, &bad).is_err());
}
